/**
 * 悍将三国 (Modern 2026 Edition) - 原生 WebSocket 实时客户端适配器
 * 
 * 架构规范：
 * 1. 彻底淘汰 2011 年陈旧且包含 null.close 报错缺陷的 socket.io-0.9.10 库；
 * 2. 采用现代 HTML5 原生 RFC 6455 WebSocket 协议与服务端 Workerman 5.x 全双工网关直连；
 * 3. 100% 保持对老客户端 io.connect()、socket.on()、socket.emit()、socket.disconnect() 的接口兼容；
 * 4. 彻底消除 TypeError: Cannot read properties of null (reading 'close') 与 (reading 'onClose')。
 *
 * 帧格式：上行 {action: 事件名, data: emit 的参数（可以是标量）, time}，服务端（Hanjiang\WebSocket\EliteRoom）只读 data；
 * 下行 {type: 事件名, data: 载荷}，data 原样交给 socket.on 回调。
 * 浏览器发不了协议级 ping 帧，连接打开后每 20 秒发一次 {action: 'ping'}，避免服务端 60 秒无活动的连接清理把连接断掉
 * （多人副本战斗期间连接留在后台，玩家可能很久不操作）；服务端回的 pong 不分发给业务。
 */
(function (window) {
    'use strict';

    class NativeSocketAdapter {
        constructor(serverUrl, options) {
            this.listeners = {};
            this.options = options || {};
            this.ws = null;
            this.connected = false;
            this.heartbeatTimer = null;
            this.heartbeatInterval = 20000;

            // 1. 标准化 WebSocket 地址：优先用调用方给的地址（elitepop.js 传 c=elite&m=get_server 返回的 url），
            //    没给（服务端未配置 socket_server_url）时用全局配置中心的 wsUrl
            var targetUrl = (typeof serverUrl === 'string' && serverUrl !== '') ? serverUrl
                : ((typeof window !== 'undefined' && window.HJ_CONFIG && window.HJ_CONFIG.wsUrl) ? window.HJ_CONFIG.wsUrl : '');
            if (!targetUrl || typeof targetUrl !== 'string') {
                targetUrl = 'ws://127.0.0.1:18101';
            }
            if (targetUrl.indexOf('http://') === 0) {
                targetUrl = targetUrl.replace('http://', 'ws://');
            } else if (targetUrl.indexOf('https://') === 0) {
                targetUrl = targetUrl.replace('https://', 'wss://');
            }

            this.url = targetUrl;
            this.initSocket();
        }

        initSocket() {
            try {
                this.ws = new WebSocket(this.url);

                this.ws.onopen = () => {
                    this.connected = true;
                    this.startHeartbeat();
                    this.trigger('connect');
                };

                this.ws.onmessage = (event) => {
                    try {
                        const packet = JSON.parse(event.data);
                        const eventName = packet.action || packet.type || 'message';
                        if (eventName === 'pong') {
                            return;
                        }
                        const payload = (packet.data !== undefined) ? packet.data : packet;
                        this.trigger(eventName, payload);
                        if (eventName !== 'message') {
                            this.trigger('message', payload);
                        }
                    } catch (e) {
                        this.trigger('message', event.data);
                    }
                };

                this.ws.onerror = (err) => {
                    this.trigger('error', err);
                };

                this.ws.onclose = (event) => {
                    this.connected = false;
                    this.stopHeartbeat();
                    this.trigger('disconnect', event);
                };
            } catch (err) {
                setTimeout(() => {
                    this.trigger('connect_failed', err);
                    this.trigger('error', err);
                }, 50);
            }
        }

        startHeartbeat() {
            this.stopHeartbeat();
            this.heartbeatTimer = setInterval(() => {
                this.emit('ping', {});
            }, this.heartbeatInterval);
        }

        stopHeartbeat() {
            if (this.heartbeatTimer) {
                clearInterval(this.heartbeatTimer);
                this.heartbeatTimer = null;
            }
        }

        on(event, handler) {
            if (!this.listeners[event]) {
                this.listeners[event] = [];
            }
            this.listeners[event].push(handler);
            return this;
        }

        emit(action, data) {
            if (this.ws && this.ws.readyState === WebSocket.OPEN) {
                const payload = JSON.stringify({
                    action: action,
                    data: data || {},
                    time: Date.now()
                });
                this.ws.send(payload);
            }
        }

        trigger(event, data) {
            const handlers = this.listeners[event] || [];
            for (let i = 0; i < handlers.length; i++) {
                try {
                    handlers[i](data);
                } catch (e) {
                    console.warn('[NativeSocket] Handler error for event:', event, e);
                }
            }
        }

        removeAllListeners(event) {
            if (event) {
                delete this.listeners[event];
            } else {
                this.listeners = {};
            }
        }

        disconnect() {
            this.stopHeartbeat();
            if (this.ws) {
                this.ws.onopen = null;
                this.ws.onmessage = null;
                this.ws.onerror = null;
                this.ws.onclose = null;
                try {
                    this.ws.close();
                } catch (e) {}
                this.ws = null;
            }
            this.connected = false;
        }

        close() {
            this.disconnect();
        }
    }

    window.io = {
        version: '2026-native-rfc6455',
        connect: function (url, options) {
            return new NativeSocketAdapter(url, options);
        }
    };
})(typeof window !== 'undefined' ? window : this);
